# v1.3.5 World Flight roster: 113 aircraft (33 WW2 / 20 Cold War / 60 Modern), all unlocked.
# cat: P plane, D drone, H helicopter, X experimental, W Wunderwaffen (WW2 German experimental)
# fields: name, short(HUD<=8), cat, era(0 WW2,1 CW,2 MOD), country, mach_max, ceiling_ft, agility 1-10,
#         endurance (game minutes at full power), rocket (0 jet/prop, 1 mothership drop, 2 ground-launched rocket),
#         fact line 1, fact line 2 (<=38 chars, neutral + factual; 'about' where figures vary), side-view spec
def _m(b,kw):d=dict(b);d.update(kw);return d
def jet(**k):return _m(dict(kind='jet',L=150,H=12,nose='point',nl=0.26,tl=0.24,canopy=(0.17,0.13,5,'bubble'),wing=(0.47,0.28,12,0.3),tail='single',th=16,intake=(0.3,0.5),paint='gray'),k)
def prop(**k):return _m(dict(kind='prop',L=112,H=13,nose='round',nl=0.14,tl=0.42,canopy=(0.36,0.14,5,'framed'),wing=(0.24,0.2,2,1),tail='single',th=13,prop=1,paint='olive'),k)
def bomber(**k):return _m(dict(kind='prop',L=176,H=17,nose='glass',nl=0.12,tl=0.36,canopy=(0.13,0.08,4,'framed'),wing=(0.3,0.17,2,0),tail='single',th=21,eng=[0.2,0.33],paint='olive'),k)
def cargo(**k):return _m(dict(kind='prop',L=170,H=20,nose='blunt',nl=0.1,tl=0.34,tailup=1,canopy=(0.05,0.07,3,'framed'),wing=(0.33,0.16,2,-1),tail='single',th=24,eng=[0.24,0.36],paint='gray'),k)
def heli(**k):return _m(dict(kind='heli',L=112,H=18,nose='round',nl=0.22,tl=0.56,canopy=(0.02,0.2,6,'glassnose'),rotor='main',tail='none',hstab=0,paint='olive'),k)
def drone(**k):return _m(dict(kind='drone',L=96,H=8,nose='round',nl=0.2,tl=0.32,wing=(0.42,0.12,0,0),tail='invv',th=10,pusher=1,paint='gray'),k)
def rkt(**k):return _m(dict(kind='rocket',L=120,H=13,nose='needle',nl=0.3,tl=0.12,canopy=(0.24,0.1,3,'flush'),wing=(0.5,0.18,6,0.3),tail='single',th=14,paint='silver'),k)
def wing(**k):return _m(dict(kind='wing',L=150,H=12,tail='none',hstab=0,canopy=(0.32,0.12,4,'flush'),paint='black'),k)
